CREATE DATABASE IF NOT EXISTS skipq CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE skipq;
CREATE TABLE users(user_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,full_name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(25) NOT NULL DEFAULT '',password_hash VARCHAR(255) NOT NULL,role ENUM('student','staff','admin') NOT NULL DEFAULT 'student',is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX ix_users_role_active(role,is_active)) ENGINE=InnoDB;
CREATE TABLE canteens(canteen_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL UNIQUE,location VARCHAR(200) NOT NULL,opening_time TIME NOT NULL,closing_time TIME NOT NULL,slot_interval_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 10,slot_capacity_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 120,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK(closing_time>opening_time),CHECK(slot_interval_minutes BETWEEN 5 AND 60),CHECK(slot_capacity_minutes>0)) ENGINE=InnoDB;
CREATE TABLE staff_canteens(user_id BIGINT UNSIGNED NOT NULL,canteen_id BIGINT UNSIGNED NOT NULL,assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,canteen_id),FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(canteen_id) REFERENCES canteens(canteen_id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE categories(category_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE menu_items(item_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,canteen_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,description VARCHAR(1000) NOT NULL DEFAULT '',price DECIMAL(10,2) NOT NULL,image_url VARCHAR(500),preparation_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 5,stock_quantity INT UNSIGNED NOT NULL DEFAULT 0,is_vegetarian BOOLEAN NOT NULL DEFAULT TRUE,is_available BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_item_canteen_name(canteen_id,name),INDEX ix_menu_filter(canteen_id,is_available,category_id),CHECK(price>0),CHECK(preparation_minutes>0),FOREIGN KEY(canteen_id) REFERENCES canteens(canteen_id),FOREIGN KEY(category_id) REFERENCES categories(category_id)) ENGINE=InnoDB;
CREATE TABLE pickup_slots(slot_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,canteen_id BIGINT UNSIGNED NOT NULL,slot_at DATETIME NOT NULL,capacity_minutes INT UNSIGNED NOT NULL,reserved_minutes INT UNSIGNED NOT NULL DEFAULT 0,UNIQUE KEY uq_canteen_slot(canteen_id,slot_at),INDEX ix_slot_date(canteen_id,slot_at),CHECK(reserved_minutes<=capacity_minutes),FOREIGN KEY(canteen_id) REFERENCES canteens(canteen_id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE orders(order_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,order_number VARCHAR(40) NOT NULL UNIQUE,customer_id BIGINT UNSIGNED NOT NULL,canteen_id BIGINT UNSIGNED NOT NULL,pickup_at DATETIME NOT NULL,subtotal DECIMAL(10,2) NOT NULL,total_amount DECIMAL(10,2) NOT NULL,order_status ENUM('PLACED','CONFIRMED','PREPARING','READY','COLLECTED','CANCELLED','REJECTED') NOT NULL DEFAULT 'PLACED',payment_status ENUM('PENDING','PAID','FAILED','REFUNDED') NOT NULL DEFAULT 'PENDING',payment_method ENUM('PICKUP','RAZORPAY') NOT NULL,pickup_code_hash VARCHAR(255) NOT NULL,pickup_verified_at DATETIME,reserved_minutes INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX ix_orders_customer(customer_id,created_at),INDEX ix_orders_canteen_status(canteen_id,order_status,pickup_at),FOREIGN KEY(customer_id) REFERENCES users(user_id),FOREIGN KEY(canteen_id) REFERENCES canteens(canteen_id),CHECK(subtotal>=0 AND total_amount>=subtotal)) ENGINE=InnoDB;
CREATE TABLE order_items(order_item_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,order_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NOT NULL,item_name VARCHAR(120) NOT NULL,quantity SMALLINT UNSIGNED NOT NULL,unit_price DECIMAL(10,2) NOT NULL,line_total DECIMAL(10,2) NOT NULL,UNIQUE KEY uq_order_item(order_id,item_id),FOREIGN KEY(order_id) REFERENCES orders(order_id) ON DELETE CASCADE,FOREIGN KEY(item_id) REFERENCES menu_items(item_id),CHECK(quantity>0),CHECK(unit_price>0),CHECK(line_total=quantity*unit_price)) ENGINE=InnoDB;
CREATE TABLE payments(payment_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,order_id BIGINT UNSIGNED NOT NULL UNIQUE,provider ENUM('razorpay','mock') NOT NULL,provider_order_id VARCHAR(100) UNIQUE,provider_payment_id VARCHAR(100) UNIQUE,amount DECIMAL(10,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'INR',payment_status ENUM('PENDING','PAID','FAILED','REFUNDED') NOT NULL DEFAULT 'PENDING',signature_verified BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(order_id),CHECK(amount>=0)) ENGINE=InnoDB;
CREATE TABLE reviews(review_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,comment VARCHAR(1000) NOT NULL DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_review_once(customer_id,order_id,item_id),FOREIGN KEY(customer_id) REFERENCES users(user_id),FOREIGN KEY(order_id) REFERENCES orders(order_id),FOREIGN KEY(item_id) REFERENCES menu_items(item_id),CHECK(rating BETWEEN 1 AND 5)) ENGINE=InnoDB;
CREATE TABLE audit_logs(audit_id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED,action VARCHAR(80) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED,details JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX ix_audit_entity(entity_type,entity_id,created_at),FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE webhook_events(event_id VARCHAR(120) PRIMARY KEY,event_type VARCHAR(100) NOT NULL,received_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
